const message = useMessage(), dialog = useDialog()
const session = ref(null), booting = ref(true), bootError = ref(''), loginBusy = ref(false), loginError = ref('')
const loginForm = reactive({ username: '', password: '', captcha: '' })
const captchaChallenge = ref(null), captchaBusy = ref(false), captchaError = ref('')
let captchaSequence = 0
async function refreshCaptcha() {
  const sequence = ++captchaSequence
  captchaBusy.value = true; captchaError.value = ''; captchaChallenge.value = null; loginForm.captcha = ''
  try {
    const challenge = await api('/auth/captcha', { method: 'POST', body: {} })
    if (sequence === captchaSequence) captchaChallenge.value = challenge
  } catch (e) {
    if (sequence === captchaSequence) captchaError.value = e.status === 429 ? '换图过于频繁，请稍后再试。' : e.status === 403 ? '访问地址与后端 server.origin 不一致，请检查配置并重启后端。' : e.status === 0 || e.status === 502 ? '无法连接后端，请确认 Go 服务已在 3080 启动。' : e.status === 404 ? '当前后端不支持验证码接口，请停止旧版本并启动最新 Go 服务。' : '验证码服务暂时不可用，点击重试。'
  } finally { if (sequence === captchaSequence) captchaBusy.value = false }
}
const viewportWidth = ref(window.innerWidth)
const isMobile = computed(() => viewportWidth.value <= 720)
function resizeViewport() { viewportWidth.value = window.innerWidth }
const page = ref('overview'), mobileMenu = ref(false), sidebarCollapsed = ref(false)
const menuCollapsed = computed(()=>sidebarCollapsed.value && !isMobile.value)
const connection = ref({ url:'', publicUrl:'', mode:'live', configured:false, apiKeyConfigured:false, connected:false, version:'', policyMode:'unknown', capabilities:{} })
