 {key:'overview',label:'概览',icon:LayoutDashboard,title:'概览'}, {key:'devices',label:'设备',icon:Monitor,title:'设备'},
 {key:'users',label:'用户',icon:Users,title:'用户'}, {key:'routes',label:'路由',icon:Route,title:'路由'},
 {key:'policy',label:'访问策略',icon:ShieldCheck,title:'访问策略'}, {key:'dns',label:'DNS',icon:Globe2,title:'DNS'},
 {key:'keys',label:'认证密钥',icon:KeyRound,title:'认证密钥'}, {key:'settings',label:'设置',icon:Settings2,title:'设置'}
]
const current = computed(()=>nav.find(n=>n.key===page.value))
const navOptions = computed(()=>nav.map(n=>({label:n.label,key:n.key,icon:()=>h(NIcon,null,{default:()=>h(n.icon,{size:18})})})))
const devices=ref([]), users=ref([]), routes=ref([]), keys=ref([])
const isDemo=computed(()=>connection.value.mode==='demo')
const canWrite=computed(()=>isDemo.value||state.connection.loaded&&connection.value.connected===true&&connection.value.capabilities?.write===true)
const canKeys=computed(()=>isDemo.value||canWrite.value&&connection.value.capabilities?.keys===true)
const canPolicyCheck=computed(()=>isDemo.value||state.connection.loaded&&state.policy.loaded&&connection.value.connected===true&&connection.value.capabilities?.policyCheck===true)
