const state=reactive(Object.fromEntries(['connection','devices','users','routes','keys','policy','dns'].map(k=>[k,{loading:false,error:'',loaded:false}])))
const pageResources={overview:['devices','users','routes'],devices:['devices','users'],users:['users','devices'],routes:['routes','devices'],keys:['keys','users'],policy:['policy'],dns:['dns'],settings:[]}
const pageErrors=computed(()=>[state.connection.error,...(pageResources[page.value]||[]).map(k=>state[k].error)].filter(Boolean))
const pageLoading=computed(()=>state.connection.loading||(pageResources[page.value]||[]).some(k=>state[k].loading))
let resourceEpoch=0, connectionSequence=0
function clearSession(){resourceEpoch++;session.value=null;drawer.value=false;selected.value=null;modal.value='';newKey.value='';devices.value=[];users.value=[];routes.value=[];keys.value=[];policy.value='';savedPolicy.value='';dnsRevision.value='';Object.assign(dns,{magic:false,domain:'',servers:'',override:false});Object.values(state).forEach(x=>Object.assign(x,{loaded:false,error:'',loading:false}));refreshCaptcha()}
async function request(path,options={}){try{return await api(path,{...options,...(options.method&&options.method!=='GET'?{csrf:session.value?.csrfToken}:{})})}catch(e){if(e.status===401){clearSession();message.warning('会话已过期，请重新登录。')}throw e}}
function explain(e){if(e.message==='policy_file_unavailable')return 'file 策略无法读取：请核对 Headscale 的 policy.path，当前提供的配置为空。Web 发布需要 database 模式，迁移前请先备份。';if(e.message==='configuration_not_configured')return 'DNS 尚未接入配置文件：请只读挂载当前 Headscale 配置，并设置管理端 configuration.path。';if(e.message==='policy_read_only')return '当前策略为只读；发布需要支持版本与 database 策略模式。';if(e.status===409)return '数据已被其他操作修改，请刷新后重试。';if(e.status===502)return 'Headscale 请求失败，请检查连接、管理 Key 或服务状态。';if(e.status===503)return '此能力尚未配置或当前服务不可用。';if(e.status===403)return '当前配置或版本不允许此操作。';return e.status===0?'无法连接控制台后端。':`请求失败：${e.message}`}
function loadDemo(){devices.value=structuredClone(demoDevices).map(d=>({...d,id:String(d.id),online:d.online,tags:d.tags||[],approvedRoutes:[],servingRoutes:[]}));users.value=structuredClone(demoUsers).map(u=>({...u,id:String(u.id)}));routes.value=structuredClone(demoRoutes).map(r=>({...r,id:String(r.id),nodeId:String(r.nodeId),serving:null}));keys.value=structuredClone(demoKeys).map(k=>({...k,id:String(k.id)}));policy.value=initialPolicy;savedPolicy.value=initialPolicy;Object.assign(dns,{magic:true,domain:'mesh.acme.internal',servers:'1.1.1.1\n8.8.8.8',override:false});Object.keys(state).forEach(k=>Object.assign(state[k],{loaded:true,error:'',loading:false}));policyInfo.writable=true;dnsWritable.value=true}
async function loadConnection(){const epoch=resourceEpoch,sequence=++connectionSequence;state.connection.loading=true;state.connection.error='';try{const result=await request('/connection');if(epoch!==resourceEpoch||sequence!==connectionSequence)return;connection.value=result;state.connection.loaded=true;if(isDemo.value)loadDemo()}catch(e){if(epoch===resourceEpoch&&sequence===connectionSequence){state.connection.loaded=false;state.connection.error=explain(e)}}finally{if(epoch===resourceEpoch&&sequence===connectionSequence)state.connection.loading=false}}
async function loadResource(k,force=false){if(isDemo.value||state[k].loading||state[k].loaded&&!force)return;const epoch=resourceEpoch;state[k].loading=true;state[k].error='';try{const data=await request(k==='dns'?'/config/dns':`/${k}`);if(epoch!==resourceEpoch)return;if(k==='policy'){policy.value=data.policy||'';savedPolicy.value=policy.value;Object.assign(policyInfo,{revision:data.revision||'',writable:data.writable===true,mode:data.mode})}else if(k==='dns'){Object.assign(dns,{magic:data.dns.magic,domain:data.dns.domain,servers:(data.dns.servers||[]).join('\n'),override:data.dns.override});dnsRevision.value=data.revision;dnsWritable.value=data.writable===true;dnsRestart.value=data.requiresRestart===true}else{({devices,users,routes,keys}[k]).value=data[k]||[]}state[k].loaded=true}catch(e){if(epoch!==resourceEpoch)return;state[k].loaded=false;state[k].error=explain(e);if(k==='dns')dnsWritable.value=false}finally{if(epoch===resourceEpoch)state[k].loading=false}}
async function loadPage(force=false){await Promise.all((pageResources[page.value]||[]).map(k=>loadResource(k,force)))}
async function restore(){booting.value=true;bootError.value='';try{session.value=await api('/auth/session')}catch(e){session.value=null;if(e.status!==401)bootError.value='控制台服务暂时不可用，请检查后端配置。'}finally{booting.value=false}if(session.value){await loadConnection();await loadPage()}else await refreshCaptcha()}
async function login(){if(!loginForm.username.trim()||!loginForm.password){loginError.value='请输入账号和密码。';return}if(!captchaChallenge.value||!loginForm.captcha.trim()){loginError.value='请输入图形验证码。';return}if(Date.parse(captchaChallenge.value.expiresAt)<=Date.now()){loginError.value='验证码已过期，请输入新验证码。';await refreshCaptcha();return}loginBusy.value=true;loginError.value='';try{session.value=await api('/auth/login',{method:'POST',body:{username:loginForm.username.trim(),password:loginForm.password,captchaId:captchaChallenge.value.captchaId,captcha:loginForm.captcha.trim()}});loginForm.password='';loginForm.captcha='';captchaChallenge.value=null;page.value='overview';await loadConnection();await loadPage();message.success('已安全登录控制台')}catch(e){session.value=null;loginError.value=e.status===429?'尝试过于频繁，请稍后再试。':e.status===401?'账号或密码错误，请重试。':e.status===400&&e.message==='invalid_captcha'?'验证码错误或已失效，请输入新验证码。':'无法完成登录，请检查后端连接。';await refreshCaptcha()}finally{loginBusy.value=false}}
async function logout(){try{await request('/auth/logout',{method:'POST'});clearSession();message.success('已退出登录')}catch(e){if(e.status!==401)message.error(explain(e))}}
function navigate(value){page.value=value;mobileMenu.value=false;window.scrollTo({top:0});loadPage()}
async function refresh(){await loadConnection();await loadPage(true)}
const query=ref(''),osFilter=ref(null),deviceTab=ref('all')
const osOptions=['Linux','macOS','Windows','iOS','Unknown'].map(value=>({label:value==='Unknown'?'未采集':value,value}))
const onlineCount=computed(()=>devices.value.filter(d=>d.online===true).length)
