const expiryMs=d=>d.expiry==='已过期'?0:Date.parse(d.expiry||'')
const isExpired=d=>Number.isFinite(expiryMs(d))&&expiryMs(d)<=Date.now()
const attention=computed(()=>devices.value.filter(d=>Number.isFinite(expiryMs(d))&&expiryMs(d)<=Date.now()+7*86400000))
const pendingRoutes=computed(()=>routes.value.filter(r=>!r.approved))
function dateLabel(value){if(!value)return '未采集';if(['永不过期','刚刚','已过期'].includes(value))return value;const n=Date.parse(value);return Number.isFinite(n)?new Date(n).toLocaleString('zh-CN',{hour12:false}):value}
function expiryLabel(d){if(!d.expiry)return '不设过期';if(isExpired(d))return '已过期';const n=expiryMs(d);if(Number.isFinite(n)&&n<=Date.now()+7*86400000)return `${Math.max(1,Math.ceil((n-Date.now())/86400000))} 天后到期`;return dateLabel(d.expiry)}
const metricValue=(k,v)=>state[k].loaded?v:'—'
const filteredDevices=computed(()=>devices.value.filter(d=>`${d.name} ${d.ip} ${d.owner} ${(d.tags||[]).join(' ')}`.toLowerCase().includes(query.value.toLowerCase())&&(deviceTab.value==='all'||deviceTab.value==='online'&&d.online===true||deviceTab.value==='offline'&&d.online===false||deviceTab.value==='attention'&&attention.value.includes(d))&&(!osFilter.value||d.platform===osFilter.value)))
const deviceIcon=d=>d.platform==='iOS'?Smartphone:d.platform==='Linux'?Server:Monitor
const statusNode=online=>h('span',{class:`online-status ${online===true?'':'offline'}`},[h('i'),online===true?'在线':online===false?'离线':'未采集'])
const tagNode=(text,type='default')=>h(NTag,{size:'small',bordered:false,type},{default:()=>text})
const deviceColumns=computed(()=>[
 {title:'设备',key:'name',minWidth:226,render:d=>h('div',{class:'device-cell'},[h('span',{class:'device-symbol'},[h(deviceIcon(d),{size:17})]),h('div',[h('button',{class:'device-link',onClick:()=>openDevice(d)},d.name),h('small',d.os||'系统未采集')])])},
 {title:'状态',key:'online',width:100,render:d=>statusNode(d.online)},{title:'IP 地址',key:'ip',width:142,render:d=>h('span',{class:'mono'},d.ip||'—')},{title:'所属用户',key:'owner',minWidth:155},
 {title:'标签',key:'tags',minWidth:148,render:d=>d.tags?.length?h('div',{class:'tags'},d.tags.map(t=>tagNode(`tag:${t}`))):'—'},
 {title:'节点过期',key:'expiry',width:140,render:d=>isExpired(d)?tagNode('已过期','error'):expiryLabel(d)},
 {title:'',key:'action',width:44,render:d=>h(NButton,{text:true,'aria-label':`查看 ${d.name}`,onClick:()=>openDevice(d)},{default:()=>h(ChevronRight,{size:16})})}
])
const overviewColumns=computed(()=>[...deviceColumns.value.filter(c=>!['expiry','action'].includes(c.key)),{title:'最近活跃',key:'last',minWidth:160,render:d=>activityLabel(d,dateLabel)},deviceColumns.value.at(-1)]),pagination={pageSize:10},rowProps=d=>({onDblclick:()=>openDevice(d)})
const selected=ref(null),drawer=ref(false),editMode=ref(false),actionBusy=ref(false)
const editForm=reactive({name:'',tags:[]})
function openDevice(d){if(!d)return;selected.value=d;editMode.value=false;drawer.value=true}
function beginEdit(){editForm.name=selected.value.name;editForm.tags=[...(selected.value.tags||[])];editMode.value=true}
async function saveDevice(){if(!canWrite.value||actionBusy.value)return;if(!/^[a-zA-Z0-9][a-zA-Z0-9-]{0,62}$/.test(editForm.name)||!editForm.tags.every(t=>/^[a-zA-Z0-9-]+$/.test(t))){message.warning('名称和标签只能包含字母、数字或连字符。');return}const d=selected.value;if(isDemo.value){Object.assign(d,{name:editForm.name,tags:[...editForm.tags]});editMode.value=false;message.success('设备已更新（演示）');return}actionBusy.value=true;let changed=false;try{if(d.name!==editForm.name){await request(`/devices/${encodeURIComponent(d.id)}/rename`,{method:'POST',body:{name:editForm.name}});changed=true}if(JSON.stringify(d.tags)!==JSON.stringify(editForm.tags)){await request(`/devices/${encodeURIComponent(d.id)}/tags`,{method:'POST',body:{tags:editForm.tags.map(t=>`tag:${t}`)}});changed=true}editMode.value=false;message.success('设备已更新')}catch(e){message.error((changed?'部分修改已生效；名称与标签不是原子操作。':'')+explain(e))}finally{await loadResource('devices',true);selected.value=devices.value.find(x=>x.id===d.id)||null;actionBusy.value=false}}
function expireDevice(){const d=selected.value;dialog.warning({title:'使节点立即过期？',content:`${d.name} 将需要重新认证，可能中断正在进行的访问。`,positiveText:'确认过期',negativeText:'取消',onPositiveClick:async()=>{if(isDemo.value){d.expiry='已过期';message.success('已模拟节点过期');return}try{await request(`/devices/${encodeURIComponent(d.id)}/expire`,{method:'POST',body:{}});await loadResource('devices',true);selected.value=devices.value.find(x=>x.id===d.id)||null;message.success('节点已过期')}catch(e){message.error(explain(e))}}})}
function deleteDevice(){const d=selected.value;dialog.warning({title:'删除设备？',content:`将从控制平面移除 ${d.name}。此操作不可撤销。`,positiveText:'确认删除',negativeText:'取消',onPositiveClick:async()=>{try{if(isDemo.value)devices.value=devices.value.filter(x=>x.id!==d.id);else{await request(`/devices/${encodeURIComponent(d.id)}`,{method:'DELETE'});await loadResource('devices',true)}drawer.value=false;selected.value=null;message.success('设备已删除')}catch(e){message.error(explain(e))}}})}
async function copy(text){try{await navigator.clipboard.writeText(text);message.success('已复制')}catch{message.warning('浏览器限制了复制，请手动选择文本复制。')}}
const modal=ref(''),joinOwner=ref(''),registrationAuthID=ref('')
const canRegister=computed(()=>isDemo.value||canWrite.value&&connection.value.capabilities?.register===true)
const joinOwnerLabel=computed(()=>users.value.find(u=>u.id===joinOwner.value)?.name||'')
const userOptions=computed(()=>users.value.map(u=>({label:u.name,value:u.id})))
function addDevice(){if(!canRegister.value)return;registrationAuthID.value='';joinOwner.value=users.value[0]?.id||'';modal.value='join'}
function registerDevice(){
 if(!canRegister.value||actionBusy.value)return
 const authId=registrationAuthID.value.trim(),userId=joinOwner.value,username=joinOwnerLabel.value
 if(!userId||!/^hskey-authreq-[A-Za-z0-9_-]{8,256}$/.test(authId)){message.warning('请选择用户，并粘贴完整 hskey-authreq- 开头的 Auth ID。');return}
 dialog.warning({title:'确认注册设备？',content:'将此待注册设备归属到 '+username+'。请确认请求来自可信设备。',positiveText:'确认注册',negativeText:'取消',onPositiveClick:async()=>{
  actionBusy.value=true
  try{
   if(isDemo.value){message.info('演示模式不批准真实注册请求。');modal.value='';return}
   const result=await request('/devices/register',{method:'POST',body:{authId,userId}})
   registrationAuthID.value='';modal.value=''
   await Promise.all([loadResource('devices',true),loadResource('users',true)])
   navigate('devices');if(result.device)openDevice(result.device)
   message.success('设备已注册，请返回客户端确认连接')
  }catch(e){message.error(e.message==='registration_failed'?'注册未完成，请确认 Auth ID 未过期、未使用且属于当前 Headscale，用户拥有所需标签权限。':explain(e))}
  finally{actionBusy.value=false}
 }})
}
function approveRoute(r){dialog.warning({title:r.approved?'撤销路由批准？':'批准这条路由？',content:`${r.cidr}。批准不等于策略放行或实际可达。`,positiveText:r.approved?'撤销批准':'确认批准',negativeText:'取消',onPositiveClick:async()=>{if(isDemo.value){r.approved=!r.approved;message.success('审批状态已更新（演示）');return}const d=devices.value.find(x=>x.id===r.nodeId);const expected=[...(d?.approvedRoutes||routes.value.filter(x=>x.nodeId===r.nodeId&&x.approved).map(x=>x.cidr))];const next=r.approved?expected.filter(c=>c!==r.cidr):[...new Set([...expected,r.cidr])];try{await request(`/routes/${encodeURIComponent(r.nodeId)}`,{method:'POST',body:{routes:next,expectedRoutes:expected}});await Promise.all([loadResource('routes',true),loadResource('devices',true)]);message.success('路由审批已更新')}catch(e){await Promise.all([loadResource('routes',true),loadResource('devices',true)]);message.error(explain(e))}}})}
const routeColumns=[{title:'宣告子网',key:'cidr',minWidth:205,render:r=>h('div',[h('strong',{class:'mono route-cidr'},r.cidr),h('small',{class:'cell-sub'},r.description)])},{title:'宣告设备',key:'nodeId',minWidth:208,render:r=>h('button',{class:'device-link',onClick:()=>openDevice(devices.value.find(d=>d.id===r.nodeId))},devices.value.find(d=>d.id===r.nodeId)?.name||r.nodeId)},{title:'设备状态',key:'online',width:114,render:r=>statusNode(devices.value.find(d=>d.id===r.nodeId)?.online)},{title:'审批状态',key:'approved',width:130,render:r=>tagNode(r.approved?'已批准':'待审批',r.approved?'info':'warning')},{title:'正在服务',key:'serving',width:125,render:r=>r.serving===null?'未采集':r.serving?'正在服务':'未服务'},{title:'',key:'action',width:128,render:r=>h(NButton,{size:'small',disabled:!canWrite.value,type:r.approved?'default':'primary',onClick:()=>approveRoute(r)},{default:()=>r.approved?'撤销批准':'批准路由'})}]
const policy=ref(''),savedPolicy=ref(''),policyTab=ref('rules'),policyInfo=reactive({revision:'',writable:false,mode:'unknown'})
const grants=computed(()=>{try{const p=JSON.parse(policy.value);return Array.isArray(p.grants)?p.grants:Array.isArray(p.acls)?null:[]}catch{return null}}),policyDirty=computed(()=>policy.value!==savedPolicy.value)
async function validatePolicy(){if(isDemo.value){try{const p=JSON.parse(policy.value);if(!Array.isArray(p.grants))throw Error('缺少 grants');message.success('JSON 与原型结构检查通过。');return true}catch(e){message.error(`格式检查未通过：${e.message}`);return false}}try{await request('/policy/check',{method:'POST',body:{policy:policy.value}});message.success('服务端策略校验通过');return true}catch(e){message.error(explain(e));return false}}
function savePolicy(){if(!canPolicyWrite.value)return;dialog.warning({title:isDemo.value?'保存策略草稿':'发布访问策略？',content:isDemo.value?'仅保留当前演示草稿。':'将发布到 Headscale，可能改变设备访问权限。请核对变更预览。',positiveText:isDemo.value?'保存演示草稿':'确认发布',negativeText:'返回编辑',onPositiveClick:async()=>{if(isDemo.value){if(await validatePolicy())savedPolicy.value=policy.value;return}try{const r=await request('/policy',{method:'PUT',body:{policy:policy.value,revision:policyInfo.revision}});savedPolicy.value=policy.value;policyInfo.revision=r.revision||policyInfo.revision;await loadResource('policy',true);message.success('策略已发布')}catch(e){message.error(explain(e));if(e.status===409)message.warning('草稿未丢弃，请复制草稿后刷新服务器版本。')}}})}
const dns=reactive({magic:false,domain:'',servers:'',override:false}),dnsRevision=ref(''),dnsWritable=ref(false),dnsRestart=ref(false),dnsPreview=ref(null)
const canDns=computed(()=>isDemo.value||state.dns.loaded&&dnsWritable.value)
async function saveDns(){if(!canDns.value)return;if(isDemo.value){message.success('DNS 演示草稿已保存');return}actionBusy.value=true;try{dnsPreview.value=await request('/config/dns/preview',{method:'POST',body:{dns:{magic:dns.magic,domain:dns.domain,servers:dns.servers.split('\n').map(x=>x.trim()).filter(Boolean),override:dns.override},revision:dnsRevision.value}});modal.value='dns-confirm'}catch(e){message.error(explain(e))}finally{actionBusy.value=false}}
async function applyDns(){if(!dnsPreview.value)return;actionBusy.value=true;try{await request('/config/dns/apply',{method:'POST',body:{token:dnsPreview.value.token,confirmed:true}});modal.value='';await loadResource('dns',true);message.success('DNS 配置已应用')}catch(e){message.error(explain(e));await loadResource('dns',true)}finally{actionBusy.value=false}}
const keyForm=reactive({name:'',owner:'',ttl:7,reusable:false}),newKey=ref('')
function createKey(){if(!canKeys.value)return;Object.assign(keyForm,{name:'',owner:users.value[0]?.id||'',ttl:7,reusable:false});newKey.value='';modal.value='key'}
async function generateKey(){if(!keyForm.name.trim()||!keyForm.owner){message.warning('请输入用途并选择用户。');return}actionBusy.value=true;try{if(isDemo.value){newKey.value=`DEMO_INVALID_${crypto.getRandomValues(new Uint32Array(2)).join('_')}`;keys.value.unshift({id:String(Date.now()),name:keyForm.name,prefix:`•••• ${newKey.value.slice(-4)}`,owner:users.value.find(u=>u.id===keyForm.owner)?.name,reusable:keyForm.reusable,expiry:new Date(Date.now()+keyForm.ttl*86400000).toISOString(),status:'有效'})}else{const r=await request('/keys',{method:'POST',body:{userId:keyForm.owner,name:keyForm.name,ttlDays:keyForm.ttl,reusable:keyForm.reusable}});newKey.value=r.key;await loadResource('keys',true)}modal.value='key-result'}catch(e){message.error(explain(e))}finally{actionBusy.value=false}}
function revokeKey(k){dialog.warning({title:'撤销这枚密钥？',content:'阻止新的设备接入，不会删除已接入设备。',positiveText:'确认撤销',negativeText:'取消',onPositiveClick:async()=>{try{if(isDemo.value)k.status='已撤销';else{await request(`/keys/${encodeURIComponent(k.id)}/expire`,{method:'POST',body:{}});await loadResource('keys',true)}message.success('密钥已撤销')}catch(e){message.error(explain(e))}}})}
const keyColumns=[{title:'用途 / 密钥',key:'name',minWidth:235,render:k=>h('div',[h('strong',{class:'table-strong'},k.name),h('small',{class:'cell-sub mono'},k.prefix)])},{title:'所属用户',key:'owner',minWidth:170},{title:'使用方式',key:'reusable',width:142,render:k=>tagNode(k.reusable?'可重复使用':'单次使用')},{title:'有效至',key:'expiry',width:145,render:k=>dateLabel(k.expiry)},{title:'状态',key:'status',width:100,render:k=>tagNode(k.status,k.status==='有效'?'info':'default')},{title:'',key:'action',width:84,render:k=>k.status==='有效'?h(NButton,{size:'small',disabled:!canKeys.value,tertiary:true,type:'error',onClick:()=>revokeKey(k)},{default:()=> '撤销'}):'—'}]
const userForm=reactive({name:'',email:''})
function createUser(){if(!canWrite.value)return;userForm.name='';userForm.email='';modal.value='user'}
async function saveUser(){if(!userForm.name.trim()||userForm.email&&!/^\S+@\S+\.\S+$/.test(userForm.email)){message.warning('请填写用户名称和有效邮箱。');return}actionBusy.value=true;try{if(isDemo.value)users.value.push({id:String(Date.now()),name:userForm.name.trim(),email:userForm.email,initial:userForm.name.slice(0,2).toUpperCase()});else{await request('/users',{method:'POST',body:{name:userForm.name.trim(),email:userForm.email}});await loadResource('users',true)}modal.value='';message.success('用户已创建')}catch(e){message.error(explain(e))}finally{actionBusy.value=false}}
function showUserDevices(u){query.value=u.name;deviceTab.value='all';osFilter.value=null;navigate('devices')}
function quickSearch(){if(!session.value)return;query.value='';navigate('devices');setTimeout(()=>document.querySelector('[data-testid=device-search] input')?.focus(),50)}
function shortcut(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickSearch()}}
let expiryTimer
watch(session,value=>{clearTimeout(expiryTimer);if(value?.expiresAt)expiryTimer=setTimeout(()=>{clearSession();message.warning('会话已过期，请重新登录。')},Math.max(0,Date.parse(value.expiresAt)-Date.now()))})
watch(modal,value=>{if(value!=='key-result')newKey.value='';if(value!=='join'){registrationAuthID.value=''}if(value!=='dns-confirm')dnsPreview.value=null})
onMounted(()=>{restore();document.addEventListener('keydown',shortcut);window.addEventListener('resize',resizeViewport)})
onUnmounted(()=>{clearTimeout(expiryTimer);document.removeEventListener('keydown',shortcut);window.removeEventListener('resize',resizeViewport)})
</script>

<template>
  <div v-if="booting" class="boot-screen"><n-spin size="large" /><p>正在验证控制台会话</p></div>
  <main v-else-if="!session" class="login-screen">
    <header class="login-header"><a class="brand headscale-brand" href="#" aria-label="Headscale Console"><span class="brand-symbol"><Network :size="24" /></span><span>Headscale</span></a></header>
    <div class="login-layout">
      <section class="login-panel"><div class="login-form-title"><h2>登录控制台</h2><p>使用控制台账号登录</p></div>
        <n-alert v-if="bootError" type="error" :bordered="false" class="login-alert">{{ bootError }}<n-button text type="primary" @click="restore">重试连接</n-button></n-alert>
        <n-form :model="loginForm" label-placement="top" @submit.prevent="login"><n-form-item label="账号"><n-input v-model:value="loginForm.username" name="username" placeholder="输入控制台账号" autocomplete="username" :disabled="loginBusy" data-testid="login-username" /></n-form-item><n-form-item label="密码"><n-input v-model:value="loginForm.password" name="password" type="password" show-password-on="click" placeholder="输入密码" autocomplete="current-password" :disabled="loginBusy" data-testid="login-password" /></n-form-item><n-form-item label="图形验证码"><div class="captcha-row"><n-input v-model:value="loginForm.captcha" placeholder="输入图中字符" :disabled="loginBusy || captchaBusy || !captchaChallenge" :maxlength="6" :input-props="{autocomplete:'off',spellcheck:false,'aria-label':'图形验证码'}" data-testid="login-captcha" /><button class="captcha-image" type="button" :disabled="loginBusy || captchaBusy" @click="refreshCaptcha" aria-label="刷新图形验证码" title="点击换图" data-testid="captcha-refresh"><img v-if="captchaChallenge" :src="captchaChallenge.image" alt="图形验证码，点击换图" width="120" height="44" data-testid="captcha-image" /><span v-else>{{ captchaBusy ? '加载中…' : '点击重试' }}</span></button></div></n-form-item><div v-if="captchaError" class="login-error" role="status">{{ captchaError }}</div><div v-if="loginError" class="login-error" role="alert">{{ loginError }}</div><n-button attr-type="submit" type="primary" block :loading="loginBusy" size="large" data-testid="login-submit">进入控制台<template #icon><ArrowRight :size="17" /></template></n-button></n-form>
      </section>
    </div>
  </main>
  <div v-else class="console-shell" :class="{'sidebar-collapsed':menuCollapsed}">
    <aside class="sidebar" :class="{open:mobileMenu}"><div class="sidebar-header"><a href="#" class="brand headscale-brand" @click.prevent="navigate('overview')" aria-label="Headscale Console"><span class="brand-symbol"><Network :size="24" /></span><span v-if="!menuCollapsed">Headscale</span></a><n-button text class="mobile-close" aria-label="关闭导航" @click="mobileMenu=false"><X :size="17" /></n-button></div><n-menu :value="page" :options="navOptions" :collapsed="menuCollapsed" :collapsed-width="72" :collapsed-icon-size="20" @update:value="navigate" /><div class="sidebar-bottom"><n-dropdown :options="[{label:'退出登录',key:'logout',icon:()=>h(LogOut,{size:16})}]" @select="logout" trigger="click"><button class="account-button" aria-label="账号菜单"><n-avatar :size="32" color="#E9EDFA" text-color="#30498E">{{ (session.username || session.user?.username || 'AD').slice(0,2).toUpperCase() }}</n-avatar><div v-if="!menuCollapsed"><strong>{{ session.username || session.user?.username || 'admin' }}</strong><small>管理员</small></div><ChevronRight v-if="!menuCollapsed" :size="15" /></button></n-dropdown></div></aside>
    <div v-if="mobileMenu" class="mobile-backdrop" @click="mobileMenu=false"></div>
    <div class="main-shell"><header class="topbar"><div class="topbar-location"><n-button text class="mobile-trigger" aria-label="打开导航" @click="mobileMenu=true"><Menu :size="21" /></n-button><n-button v-if="!isMobile" text :aria-label="menuCollapsed?'展开侧栏':'收起侧栏'" :aria-expanded="!menuCollapsed" @click="sidebarCollapsed=!sidebarCollapsed" data-testid="sidebar-toggle"><Menu :size="21" /></n-button></div><div class="topbar-actions"><button class="global-search" @click="quickSearch"><Search :size="15" /><span>搜索设备</span><kbd>⌘ / Ctrl K</kbd></button><n-tag :bordered="false" size="small" :type="isDemo || connection.connected ? 'info' : 'warning'">{{ isDemo ? '演示模式' : connection.connected ? '已连接' : '未连接' }}</n-tag></div></header>
      <main class="page-content"><header class="page-heading"><div><h1>{{ current.label }}</h1><span v-if="page==='devices'" class="page-subtitle">{{ metricValue('devices',devices.length) }} 台设备</span></div><div class="page-actions">
        <n-button v-if="page==='overview' || page==='settings'" @click="refresh" data-testid="refresh"><template #icon><RefreshCw :size="15" /></template>刷新</n-button>
        <n-button v-if="page==='overview' || page==='devices'" type="primary" @click="addDevice" :disabled="!canRegister" data-testid="add-device"><template #icon><Plus :size="17" /></template>添加设备</n-button>
        <n-button v-if="page==='users'" type="primary" @click="createUser" :disabled="!canWrite"><template #icon><Plus :size="17" /></template>创建用户</n-button>
        <n-button v-if="page==='routes'" @click="modal='route-guide'"><template #icon><Terminal :size="16" /></template>接入指南</n-button>
        <template v-if="page==='policy'"><n-button @click="validatePolicy" :disabled="!canPolicyCheck" data-testid="validate-policy"><template #icon><Check :size="16" /></template>检查格式</n-button><n-button type="primary" @click="savePolicy" :disabled="!canPolicyWrite">{{ isDemo ? '保存草稿' : '发布策略' }}</n-button></template>
        <n-button v-if="page==='dns'" type="primary" @click="saveDns" :disabled="!canDns" :loading="actionBusy" data-testid="dns-preview">{{ isDemo ? '保存草稿' : '预览变更' }}</n-button>
        <n-button v-if="page==='keys'" type="primary" @click="createKey" :disabled="!canKeys" data-testid="create-key"><template #icon><Plus :size="17" /></template>创建密钥</n-button>
      </div></header>
      <n-alert v-for="error in pageErrors" :key="error" type="error" :bordered="false" class="page-alert" data-testid="load-error">{{ error }} <n-button text @click="refresh">重试</n-button></n-alert><n-alert v-if="!isDemo && connection.connected && !canWrite" type="warning" :bordered="false" class="page-alert">Headscale {{ connection.version || '版本未识别' }}：当前版本或部署配置不支持写入，只读浏览。</n-alert><div v-if="pageLoading" class="loading-note"><n-spin size="small" />加载数据…</div>

      <template v-if="page==='overview'">
        <section class="metrics-strip"><div class="metric"><div class="metric-label">接入设备<Monitor :size="16" /></div><div class="metric-number">{{ metricValue('devices',devices.length) }}<span>台</span></div><div class="metric-detail" v-if="state.devices.loaded"><span class="status-dot"></span>{{ onlineCount }} 台在线<span class="metric-sep">·</span>{{ offlineCount }} 台离线</div></div><div class="metric"><div class="metric-label">网络用户<Users :size="16" /></div><div class="metric-number">{{ metricValue('users',users.length) }}<span>位</span></div></div><div class="metric"><div class="metric-label">子网路由<Route :size="16" /></div><div class="metric-number">{{ metricValue('routes',routes.length) }}<span>条</span></div><div class="metric-detail" v-if="state.routes.loaded">{{ routes.filter(r=>r.approved).length }} 已批准<span class="metric-sep">·</span><span :class="{'text-amber':pendingRoutes.length}">{{ pendingRoutes.length }} 待审批</span></div></div><div class="metric"><div class="metric-label">需要关注<ShieldCheck :size="16" /></div><div class="metric-number">{{ metricValue('devices',attention.length) }}<span>台</span></div><div class="metric-detail" v-if="state.devices.loaded">{{ attention.filter(d=>!isExpired(d)).length }} 即将到期<span class="metric-sep">·</span>{{ attention.filter(d=>isExpired(d)).length }} 已过期</div></div></section>
        <section class="connection-summary" data-testid="connection-summary"><div class="section-heading"><h2>网络连接概况</h2><span class="section-meta">控制面状态 · 非流量监控</span></div><div class="connection-content"><div class="connection-state"><Network :size="24" /><div><strong>{{ isDemo ? '演示网络' : connection.connected && state.connection.loaded ? 'Headscale 已连接' : '连接状态待确认' }}</strong><p>{{ isDemo ? '内置演示快照' : connection.version || '版本未识别' }}</p></div></div><div class="connection-details"><div class="connection-counts"><button @click="viewDeviceStatus('online')"><span class="status-dot"></span>在线 <strong>{{ metricValue('devices',onlineCount) }}</strong></button><button @click="viewDeviceStatus('offline')"><span class="status-dot offline-dot"></span>离线 <strong>{{ metricValue('devices',offlineCount) }}</strong></button><span v-if="unknownCount">未采集 {{ unknownCount }}</span></div><div class="connection-bar" v-if="state.devices.loaded && devices.length" role="img" :aria-label="`${onlineCount} 台在线，${offlineCount} 台离线，${unknownCount} 台状态未知`"><span :style="{width:onlinePercent+'%'}"></span></div><p>子网路由：{{ metricValue('routes',routes.filter(r=>r.approved).length) }} 已批准 · {{ metricValue('routes',pendingRoutes.length) }} 待审批</p></div></div></section>
        <section v-if="pendingRoutes.length || attention.length" class="overview-todos"><h2>待处理</h2><div class="todo-list"><button v-for="r in pendingRoutes" :key="'r'+r.id" class="todo-compact" @click="navigate('routes')"><Route :size="17" /><span>{{ r.cidr }}</span><span class="todo-label">待批准</span><ChevronRight :size="16" /></button><button v-for="d in attention" :key="d.id" class="todo-compact" @click="openDevice(d)"><LockKeyhole :size="17" /><span>{{ d.name }}</span><span class="todo-label">{{ expiryLabel(d) }}</span><ChevronRight :size="16" /></button></div></section>
        <section class="device-preview"><div class="section-heading"><div class="heading-inline"><h2>设备速览</h2><span class="section-meta">最近活跃的设备</span></div><n-button text type="primary" @click="navigate('devices')">全部设备<template #icon><ArrowRight :size="15" /></template></n-button></div><div v-if="isMobile" class="mobile-device-list"><article v-for="d in overviewDevices" :key="d.id" class="mobile-device-card" data-testid="device-card"><header><button class="device-link" @click="openDevice(d)">{{ d.name }}</button><span :class="['online-status',{offline:d.online!==true}]"><i></i>{{ d.online===true?'在线':d.online===false?'离线':'未采集' }}</span></header><div class="mobile-device-ip"><code>{{ d.ip || '—' }}</code><span>{{ d.os || '系统未采集' }}</span></div><dl><div><dt>所属用户</dt><dd>{{ d.owner || '—' }}</dd></div><div><dt>节点过期</dt><dd>{{ expiryLabel(d) }}</dd></div><div v-if="page==='overview'"><dt>最近活跃</dt><dd>{{ activityLabel(d,dateLabel) }}</dd></div></dl><div class="mobile-device-footer"><div class="tags"><n-tag v-for="t in d.tags" :key="t" :bordered="false" size="small">tag:{{ t }}</n-tag></div><n-button size="small" @click="openDevice(d)">详情<template #icon><ChevronRight :size="14" /></template></n-button></div></article><n-empty v-if="!overviewDevices.length && state.devices.loaded" description="没有匹配设备" /></div><n-data-table v-else :columns="overviewColumns" :data="overviewDevices" :bordered="false" :single-line="true" :scroll-x="1060" :row-key="d=>d.id" /></section>
      </template>

      <template v-else-if="page==='devices'"><n-tabs v-model:value="deviceTab" type="line" class="main-tabs"><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="all" :tab="`全部设备 ${devices.length}`" /><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="online" :tab="`在线 ${onlineCount}`" /><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="offline" :tab="`离线 ${offlineCount}`" /><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="attention" :tab="`需要关注 ${attention.length}`" /></n-tabs><div class="table-toolbar"><n-space><n-input v-model:value="query" clearable placeholder="搜索名称、IP、所属用户…" class="device-search" data-testid="device-search"><template #prefix><Search :size="16" /></template></n-input><n-select v-model:value="osFilter" :options="osOptions" clearable placeholder="所有操作系统" class="os-filter" /></n-space><span class="section-meta">{{ state.devices.loaded ? filteredDevices.length : '—' }} 台设备</span></div><div v-if="isMobile" class="mobile-device-list"><article v-for="d in filteredDevices" :key="d.id" class="mobile-device-card" data-testid="device-card"><header><button class="device-link" @click="openDevice(d)">{{ d.name }}</button><span :class="['online-status',{offline:d.online!==true}]"><i></i>{{ d.online===true?'在线':d.online===false?'离线':'未采集' }}</span></header><div class="mobile-device-ip"><code>{{ d.ip || '—' }}</code><span>{{ d.os || '系统未采集' }}</span></div><dl><div><dt>所属用户</dt><dd>{{ d.owner || '—' }}</dd></div><div><dt>节点过期</dt><dd>{{ expiryLabel(d) }}</dd></div><div v-if="page==='overview'"><dt>最近活跃</dt><dd>{{ activityLabel(d,dateLabel) }}</dd></div></dl><div class="mobile-device-footer"><div class="tags"><n-tag v-for="t in d.tags" :key="t" :bordered="false" size="small">tag:{{ t }}</n-tag></div><n-button size="small" @click="openDevice(d)">详情<template #icon><ChevronRight :size="14" /></template></n-button></div></article><n-empty v-if="!filteredDevices.length && state.devices.loaded" description="没有匹配设备" /></div><n-data-table v-else :columns="deviceColumns" :data="filteredDevices" :bordered="false" :pagination="pagination" :scroll-x="1040" :row-key="d=>d.id" :row-props="rowProps" /></template>

      <template v-else-if="page==='users'"><div class="users-grid"><article v-for="u in users" :key="u.id" class="user-item"><div class="user-heading"><n-avatar :size="43" color="#EFF2FA" text-color="#3C4E7E">{{ u.initial }}</n-avatar><div><h3>{{ u.name }}</h3><p>{{ u.email }}</p></div></div><div class="user-stats"><span><strong>{{ devices.filter(d=>d.owner===u.name).length }}</strong> 台设备</span><span><i class="status-dot"></i>{{ devices.filter(d=>d.owner===u.name&&d.online).length }} 台在线</span></div><n-button secondary @click="showUserDevices(u)">查看所属设备<template #icon><ArrowRight :size="15" /></template></n-button></article></div><n-empty v-if="!users.length" description="尚未加载网络用户" /></template>

      <template v-else-if="page==='routes'"><div class="compact-stats"><span><strong>{{ routes.length }}</strong> 已宣告</span><span><strong>{{ routes.filter(r=>r.approved).length }}</strong> 已批准</span><span class="text-amber"><strong>{{ pendingRoutes.length }}</strong> 待审批</span></div><n-data-table :columns="routeColumns" :data="routes" :bordered="false" :scroll-x="950" :row-key="r=>r.id" /><div v-if="!routes.some(r=>r.cidr==='0.0.0.0/0'||r.cidr==='::/0')" class="exit-section"><div class="exit-icon"><Globe2 :size="23" /></div><div><h3>退出节点</h3><p>目前没有已加载的默认路由。由设备宣告、管理员批准，再由客户端选用。</p></div><n-button @click="modal='route-guide'">查看配置</n-button></div><p class="helper-note">已批准不等于实际可达；未知的服务状态显示“未采集”。</p></template>

      <template v-else-if="page==='policy'"><n-tabs v-model:value="policyTab" type="line" class="main-tabs"><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="rules" tab="规则概览" /><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="source" tab="策略源码" /><n-tab role="tab" tabindex="0" @keydown.enter="$event.currentTarget.click()" @keydown.space.prevent="$event.currentTarget.click()" name="changes" tab="变更预览" /></n-tabs><div class="policy-layout"><div class="policy-main"><div class="editor-heading"><span><Code2 :size="15" />Grants · {{ policyTab==='rules'?'只读概览':'策略源码' }}</span><n-tag :bordered="false" size="small" :type="policyDirty?'warning':'default'">{{ policyDirty?'有未保存修改':'草稿已保存' }}</n-tag></div><template v-if="policyTab==='rules'"><div v-for="(g,i) in grants" :key="i" class="grant-row"><div class="grant-index">{{ String(i+1).padStart(2,'0') }}</div><div class="grant-content"><div class="grant-meta">允许访问<n-tag size="small" :bordered="false" type="info">GRANT</n-tag></div><div class="grant-flow"><n-tag v-for="s in g.src" :key="s" :bordered="false">{{ s }}</n-tag><ArrowRight :size="16" /><n-tag v-for="d in g.dst" :key="d" :bordered="false" type="info">{{ d }}</n-tag></div><div class="grant-ports">IP / 协议端口 <code>{{ g.ip.join(', ') }}</code></div></div></div><n-alert v-if="grants===null" type="info">策略可能包含 HuJSON 注释，请使用源码编辑；概览无法解析不代表策略无效。</n-alert><n-empty v-else-if="!grants.length" :description="!policy.trim() ? '尚无策略记录，请在源码中创建并校验；空策略不代表默认隔离。' : '当前草稿没有允许规则'" /><n-button text type="primary" class="edit-source-button" @click="policyTab='source'">在源码中编辑<template #icon><ArrowRight :size="15" /></template></n-button></template><n-input v-else-if="policyTab==='source'" v-model:value="policy" type="textarea" :autosize="{minRows:19,maxRows:30}" class="policy-code" :input-props="{spellcheck:false,'aria-label':'Grants 策略 JSON'}" data-testid="policy-editor" /><div v-else class="diff-view"><div><h4>已保存草稿</h4><n-code :code="savedPolicy" language="json" word-wrap /></div><div><h4>当前草稿</h4><n-code :code="policy" language="json" word-wrap /></div></div><div class="editor-footer">{{ isDemo ? '仅保存演示草稿，不发布到 Headscale。' : '发布前请检查变更；file 模式仅允许读取。' }}</div></div></div></template>

      <template v-else-if="page==='dns'"><n-alert v-if="!isDemo && !state.dns.loading && !state.dns.loaded" type="info" :bordered="false">DNS 需要读取当前 Headscale 配置；挂载 configuration.path 后可只读查看，不必开启写入。</n-alert><div class="settings-layout" v-if="isDemo || state.dns.loaded"><section class="settings-main"><div class="section-heading"><h2>名称解析</h2></div><div class="setting-row"><div><h3>MagicDNS</h3><p>为网络内设备生成可解析的域名</p></div><n-switch v-model:value="dns.magic" :disabled="!canDns" aria-label="MagicDNS" /></div><n-form label-placement="top" class="dns-form"><n-form-item label="网络基础域名"><n-input v-model:value="dns.domain" :disabled="!canDns" placeholder="mesh.example.com" data-testid="dns-domain" /></n-form-item><p class="field-help">对应 Headscale 的 base_domain 配置。</p><n-form-item label="全局 DNS 服务器"><n-input v-model:value="dns.servers" :disabled="!canDns" type="textarea" :autosize="{minRows:3}" placeholder="每行一个 IP 地址" /></n-form-item><p class="field-help">每行一个 DNS 服务器地址。</p></n-form><div class="setting-row"><div><h3>覆盖客户端本地 DNS</h3><p>优先使用配置的全局名称服务器</p></div><n-switch v-model:value="dns.override" :disabled="!canDns" aria-label="覆盖本地 DNS" /></div></section></div></template>

      <template v-else-if="page==='keys'"><n-data-table :columns="keyColumns" :data="keys" :bordered="false" :scroll-x="890" :row-key="k=>k.id" /><p class="helper-note keys-note" data-testid="keys-note">{{ isDemo ? '演示密钥不可用于接入；明文仅展示一次。' : '密钥明文仅展示一次，不在列表中保存。' }}</p></template>

      <template v-else-if="page==='settings'"><div class="settings-layout"><section class="settings-main"><div class="section-heading"><h2>Headscale 连接</h2><n-tag size="small" :bordered="false" type="info">部署时配置</n-tag></div><div class="deployment-field"><span>服务地址</span><code data-testid="configured-url">{{ connection.url || '尚未配置' }}</code><p>部署配置，只读。</p></div><div class="deployment-field"><span>管理 API Key</span><div class="key-config-status" data-testid="key-status"><ShieldCheck :size="17" />{{ connection.apiKeyConfigured?'已在服务端配置':'尚未配置' }}</div><p>凭据仅保存在后端。</p></div><div class="deployment-field"><span>业务状态</span><div>{{ isDemo ? '演示模式' : connection.connected ? 'Headscale ' + connection.version : '连接失败或尚未配置' }}</div><p>后端：Go。页面不会持有管理 API Key。</p></div><div class="section-heading security-title"><h2>控制台访问</h2><LockKeyhole :size="17" /></div><div class="setting-row"><div><h3>独立账号密码</h3><p>当前账号：{{ session.username || session.user?.username || 'admin' }}</p></div><n-tag size="small" :bordered="false" type="info">已启用</n-tag></div><div class="setting-row"><div><h3>服务端会话</h3><p>HttpOnly Cookie，不使用前端 Token 持久化。</p></div><n-button @click="logout" data-testid="logout"><template #icon><LogOut :size="15" /></template>退出登录</n-button></div></section></div></template>
      
      </main>
    </div>
  </div>

  <n-drawer v-model:show="drawer" :width="Math.min(460, viewportWidth)" :auto-focus="true" placement="right"><n-drawer-content title="设备详情" closable><template v-if="selected"><div class="drawer-device-heading"><div class="drawer-device-icon"><component :is="deviceIcon(selected)" :size="26" /></div><div><h2>{{ selected.name }}</h2><span :class="['online-status',{'offline':!selected.online}]"><i></i>{{ selected.online===true ? '在线' : selected.online===false ? '离线' : '未采集' }}</span><span class="drawer-os">{{ selected.os }}</span></div></div><n-form v-if="editMode" label-placement="top"><n-form-item label="设备名称"><n-input v-model:value="editForm.name" data-testid="edit-device-name" /></n-form-item><n-form-item label="所属用户"><n-input :value="selected.owner" disabled /></n-form-item><p class="field-help">新版 Headscale 不支持直接修改节点所有权。</p><n-form-item label="标签"><n-select v-model:value="editForm.tags" multiple filterable tag :options="['prod','dev','router','office','ci','test'].map(t=>({label:t,value:t}))" /></n-form-item><n-space><n-button @click="editMode=false">取消</n-button><n-button type="primary" @click="saveDevice" data-testid="save-device" :loading="actionBusy">{{ isDemo ? '保存演示修改' : '保存修改' }}</n-button></n-space></n-form><template v-else><n-descriptions label-placement="left" :column="1" :bordered="false" class="device-descriptions"><n-descriptions-item label="IPv4 地址"><code>{{ selected.ip }}</code></n-descriptions-item><n-descriptions-item label="所属用户">{{ selected.owner }}</n-descriptions-item><n-descriptions-item label="客户端版本">{{ selected.version || '未采集' }}</n-descriptions-item><n-descriptions-item label="最后在线">{{ dateLabel(selected.last) }}</n-descriptions-item><n-descriptions-item label="节点密钥过期">{{ expiryLabel(selected) }}</n-descriptions-item><n-descriptions-item label="MagicDNS"><code v-if="dns.domain" class="break-word">{{ selected.name }}.{{ dns.domain }}</code><span v-else>未采集</span></n-descriptions-item></n-descriptions><div class="drawer-section"><h3>访问标签</h3><n-space v-if="selected.tags.length"><n-tag v-for="t in selected.tags" :key="t" :bordered="false" size="small">tag:{{ t }}</n-tag></n-space><span v-else class="muted">未设置标签</span></div><div class="drawer-section"><h3>宣告路由</h3><div v-for="cidr in selected.routes" :key="cidr" class="drawer-route"><code>{{ cidr }}</code><n-tag :bordered="false" size="small" :type="routes.find(r=>r.cidr===cidr)?.approved?'info':'warning'">{{ routes.find(r=>r.cidr===cidr)?.approved?'已批准':'待审批' }}</n-tag></div><span v-if="!selected.routes.length" class="muted">此设备没有宣告子网路由</span></div><n-space class="drawer-actions"><n-button @click="beginEdit" :disabled="!canWrite" data-testid="edit-device"><template #icon><SlidersHorizontal :size="15" /></template>编辑设备</n-button><n-button @click="copy(selected.ip)"><template #icon><Copy :size="15" /></template>复制 IP</n-button></n-space><div class="drawer-danger"><h3>节点认证</h3><p>立即过期可能中断访问，设备需要重新认证。</p><n-button v-if="!isExpired(selected)" type="error" secondary @click="expireDevice" :disabled="!canWrite">使节点立即过期</n-button><n-button v-else @click="drawer=false;addDevice()" :disabled="!canKeys">重新接入</n-button><n-button type="error" text @click="deleteDevice" :disabled="!canWrite" style="margin-left:14px">删除设备</n-button></div></template></template></n-drawer-content></n-drawer>

  <n-modal :show="!!modal" @update:show="v=>{if(!v)modal=''} " preset="card" :title="({'dns-confirm':'确认 DNS 配置变更','join':'接入一台设备','key':'创建预授权密钥','key-result':'密钥已创建','user':'创建网络用户','route-guide':'路由接入指南'})[modal]" class="console-modal" :bordered="false" :mask-closable="modal!=='key-result'">
    <template v-if="modal==='dns-confirm' && dnsPreview"><n-alert :type="dnsPreview.requiresRestart?'warning':'info'" :bordered="false">{{ dnsPreview.requiresRestart ? '应用后将重启 Headscale，可能短暂中断控制面。' : '应用 DNS 配置变更。' }}</n-alert><div class="diff-view"><div><h4>修改前</h4><n-code :code="JSON.stringify(dnsPreview.before,null,2)" word-wrap /></div><div><h4>修改后</h4><n-code :code="JSON.stringify(dnsPreview.after,null,2)" word-wrap /></div></div><p class="helper-note">确认令牌短时有效；并发修改或超时后需重新预览。</p><div class="modal-actions"><n-button @click="modal=''">取消</n-button><n-button type="primary" :loading="actionBusy" @click="applyDns" data-testid="apply-dns">确认应用</n-button></div></template><template v-else-if="modal==='join'"><n-form label-placement="top"><n-form-item label="注册 Auth ID"><n-input v-model:value="registrationAuthID" placeholder="hskey-authreq-...（从客户端注册网页复制）" :input-props="{autocomplete:'off',spellcheck:false}" data-testid="register-auth-id" /></n-form-item><n-form-item label="所属用户"><n-select v-model:value="joinOwner" :options="userOptions" placeholder="选择设备归属用户" /></n-form-item></n-form><p class="helper-note">客户端先登录 Headscale，复制注册网页的 Auth ID，在这里批准注册。</p><div class="modal-actions"><n-button @click="modal=''">取消</n-button><n-button type="primary" @click="registerDevice" :loading="actionBusy" :disabled="!canRegister" data-testid="join-next">注册设备</n-button></div></template>
    <template v-else-if="modal==='key'"><n-form label-placement="top"><n-form-item label="用途名称"><n-input v-model:value="keyForm.name" placeholder="例如：生产服务器接入" data-testid="key-name" /></n-form-item><n-form-item label="所属用户"><n-select v-model:value="keyForm.owner" :options="userOptions" /></n-form-item><n-form-item label="有效期"><n-select v-model:value="keyForm.ttl" :options="[{label:'1 天',value:1},{label:'7 天',value:7},{label:'30 天',value:30}]" /></n-form-item><div class="setting-row"><div><h3>可重复使用</h3><p>仅用于受控批量接入；泄露后可被复用。</p></div><n-switch v-model:value="keyForm.reusable" /></div></n-form><div class="modal-actions"><n-button @click="modal=''">取消</n-button><n-button type="primary" @click="generateKey" :loading="actionBusy" data-testid="generate-key">{{ isDemo ? '创建演示密钥' : '创建密钥' }}</n-button></div></template>
    <template v-else-if="modal==='key-result'"><n-alert type="warning" :bordered="false">{{ isDemo ? '此值仅供演示，不能接入设备。' : '明文仅展示一次，请妥善保管。' }}</n-alert><div class="command-box" data-testid="new-key">{{ newKey }}</div><n-button @click="copy(newKey)"><template #icon><Copy :size="15" /></template>{{ isDemo ? '复制演示值' : '复制密钥' }}</n-button><div class="modal-actions"><n-button type="primary" @click="modal='';newKey=''">我已知晓</n-button></div></template>
    <template v-else-if="modal==='user'"><n-form label-placement="top"><n-form-item label="用户名称"><n-input v-model:value="userForm.name" placeholder="用户名称" /></n-form-item><n-form-item label="邮箱"><n-input v-model:value="userForm.email" placeholder="name@example.com" /></n-form-item></n-form><p class="helper-note">网络用户不赋予控制台登录权限。</p><div class="modal-actions"><n-button @click="modal=''">取消</n-button><n-button type="primary" @click="saveUser" :loading="actionBusy">{{ isDemo ? '创建演示用户' : '创建用户' }}</n-button></div></template>
    <template v-else-if="modal==='route-guide'"><div class="guide-step"><b>01</b><div><h3>启用 IP 转发</h3><p>按操作系统开启 IPv4 / IPv6 forwarding，检查防火墙。</p></div></div><div class="guide-step"><b>02</b><div><h3>客户端宣告子网</h3><div class="command-box">tailscale set --advertise-routes=172.16.0.0/16</div></div></div><div class="guide-step"><b>03</b><div><h3>批准并配置访问策略</h3><p>控制台批准路由，Linux 使用方通常还需启用 accept-routes。</p></div></div><div class="guide-step"><b>04</b><div><h3>按需宣告退出节点</h3><div class="command-box">tailscale set --advertise-exit-node</div><p>批准默认路由后，由客户端主动选用互联网出口。</p></div></div></template>
    
  </n-modal>
</template>
